// 1. 全局弹窗控制函数
window.openCreateDrawer = function(defaultType = 'task') {
  const modal = document.getElementById('create-modal-backdrop');
  if (modal) {
    modal.style.display = 'flex';
    switchCreateTab(defaultType);
    setTimeout(() => {
      const input = defaultType === 'task' 
        ? document.getElementById('task-title-input') 
        : document.getElementById('note-title-input');
      if (input) input.focus();
    }, 50);
  }
};

window.closeCreateDrawer = function() {
  const modal = document.getElementById('create-modal-backdrop');
  if (modal) modal.style.display = 'none';
};

window.switchCreateTab = function(type) {
  const taskTab = document.getElementById('modal-tab-task');
  const noteTab = document.getElementById('modal-tab-note');
  const taskForm = document.getElementById('modal-form-task');
  const noteForm = document.getElementById('modal-form-note');

  if (!taskTab || !noteTab || !taskForm || !noteForm) return;

  if (type === 'task') {
    taskTab.classList.add('active');
    noteTab.classList.remove('active');
    taskForm.style.display = 'flex';
    noteForm.style.display = 'none';
    const input = document.getElementById('task-title-input');
    if (input) input.focus();
  } else {
    noteTab.classList.add('active');
    taskTab.classList.remove('active');
    noteForm.style.display = 'flex';
    taskForm.style.display = 'none';
    const input = document.getElementById('note-title-input');
    if (input) input.focus();
  }
};

window.toggleTheme = function() {
  const current = document.documentElement.getAttribute('data-theme');
  document.documentElement.setAttribute('data-theme', current === 'dark' ? 'light' : 'dark');
};

